<?php
declare(strict_types=1); namespace App\Services; use App\Core\Database;use App\Core\Request;use PDOException;
class PersonnelService { private function school():int{return (int)(Request::get('auth_user',[])['school_id']??0);} private function number(int $s):string{$q=Database::connect()->prepare('SELECT COUNT(*) FROM personnel_profiles WHERE school_id=?');$q->execute([$s]);return 'PERS-'.$s.'-'.str_pad((string)((int)$q->fetchColumn()+1),5,'0',STR_PAD_LEFT);} public function nextNumber():array{$s=$this->school();return $s?['personnel_number'=>$this->number($s)]:['error'=>'Établissement introuvable'];}
public function all(array $f=[]):array{$s=$this->school();if(!$s)return[];$w=['school_id=?'];$p=[$s];foreach(['personnel_type','status','service_assignment'] as $k)if(!empty($f[$k])){$w[]="$k=?";$p[]=$f[$k];}$q=trim((string)($f['search']??''));if($q!==''){$w[]='(first_name LIKE ? OR last_name LIKE ? OR personnel_number LIKE ? OR cin LIKE ?)';$q='%'.$q.'%';array_push($p,$q,$q,$q,$q);} $st=Database::connect()->prepare('SELECT * FROM personnel_profiles WHERE '.implode(' AND ',$w).' ORDER BY last_name,first_name');$st->execute($p);return $st->fetchAll();}
public function one(int $id):array|false{$s=$this->school();$q=Database::connect()->prepare('SELECT * FROM personnel_profiles WHERE id=? AND school_id=?');$q->execute([$id,$s]);return$q->fetch()?:false;} private function data(array $d,int $s):array{$a=trim((string)($d['first_name']??''));$b=trim((string)($d['last_name']??''));$t=(string)($d['personnel_type']??'');$phone=trim((string)($d['phone']??''));$job=trim((string)($d['job_title']??($d['job_function']??'')));if(!$a||!$b||!$phone||!$job||!in_array($t,['TEACHER','ADMINISTRATIVE_STAFF'],true))return['error'=>'Type, nom, prénom, téléphone et poste obligatoires'];$cin=strtoupper(preg_replace('/\s+/','',(string)($d['cin']??'')));$n=fn($k)=>trim((string)($d[$k]??''))?:null;return['first_name'=>$a,'last_name'=>$b,'personnel_type'=>$t,'cin'=>$cin?:null,'phone'=>$phone,'email'=>$n('email'),'gender'=>$n('gender'),'entry_date'=>$n('entry_date'),'job_title'=>$job,'job_function'=>$n('job_function'),'contract_type'=>$n('contract_type'),'specialty'=>$n('specialty'),'service_assignment'=>$n('service_assignment'),'administrative_department'=>$n('administrative_department'),'primary_mission'=>$n('primary_mission')];}
public function create(array $d):array{$s=$this->school();$v=$this->data($d,$s);if(isset($v['error']))return$v;$num=$this->number($s);try{$q=Database::connect()->prepare('INSERT INTO personnel_profiles (school_id,personnel_number,first_name,last_name,cin,phone,email,gender,entry_date,job_title,job_function,contract_type,personnel_type,specialty,service_assignment,administrative_department,primary_mission,status) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,"ACTIF")');$q->execute([$s,$num,$v['first_name'],$v['last_name'],$v['cin'],$v['phone'],$v['email'],$v['gender'],$v['entry_date'],$v['job_title'],$v['job_function'],$v['contract_type'],$v['personnel_type'],$v['specialty'],$v['service_assignment'],$v['administrative_department'],$v['primary_mission']]);return['id'=>(int)Database::connect()->lastInsertId(),'personnel_number'=>$num,'status'=>'ACTIF'];}catch(PDOException $e){return['error'=>(int)$e->getCode()===23000?'Matricule ou CIN déjà utilisé dans cet établissement':'Création impossible'];}}
public function update(int $id,array $d):array{$x=$this->one($id);if(!$x)return['error'=>'Personnel introuvable'];$v=$this->data(array_merge($x,$d),$this->school());if(isset($v['error']))return$v;try{$q=Database::connect()->prepare('UPDATE personnel_profiles SET first_name=?,last_name=?,cin=?,phone=?,email=?,gender=?,entry_date=?,job_title=?,job_function=?,contract_type=?,personnel_type=?,specialty=?,service_assignment=?,administrative_department=?,primary_mission=? WHERE id=? AND school_id=?');$q->execute([$v['first_name'],$v['last_name'],$v['cin'],$v['phone'],$v['email'],$v['gender'],$v['entry_date'],$v['job_title'],$v['job_function'],$v['contract_type'],$v['personnel_type'],$v['specialty'],$v['service_assignment'],$v['administrative_department'],$v['primary_mission'],$id,$this->school()]);return['id'=>$id];}catch(PDOException $e){return['error'=>'CIN déjà utilisé dans cet établissement'];}}
public function status(int $id,string $status):array{$x=$this->one($id);if(!$x)return['error'=>'Personnel introuvable'];if(!in_array($status,['ACTIF','EN_CONGE','ARCHIVE'],true))return['error'=>'Statut invalide'];Database::connect()->prepare('UPDATE personnel_profiles SET status=? WHERE id=? AND school_id=?')->execute([$status,$id,$this->school()]);return['id'=>$id,'status'=>$status];}}
